function escapeHtml(str) {
  if (!str) return '';
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function formatNum(n) {
  if (!n) return '0';
  if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
  if (n >= 10000) return (n / 10000).toFixed(1) + '万';
  if (n >= 1000) return (n / 1000).toFixed(1) + 'k';
  return n.toString();
}

// ==========================================
// DYNAMIC REAL-TIME SNOWFLAKE CLOCK ENGINE
// ==========================================
function getTweetSnowflakeMs(t) {
  let id = t.id;
  if (!id || !/^\d+$/.test(id)) {
    const m = t.url ? t.url.match(/\/status\/(\d+)/) : null;
    if (m) id = m[1];
  }
  if (id && /^\d+$/.test(id)) {
    try {
      const tid = BigInt(id);
      const epoch = 1288834974657n;
      const ms = Number((tid >> 22n) + epoch);
      if (ms > 1577836800000 && ms <= Date.now() + 300000) {
        return ms;
      }
    } catch (e) {}
  }
  if (t.created_at) {
    const parsed = new Date(t.created_at).getTime();
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return null;
}

function getTweetAgeHours(t) {
  const ms = getTweetSnowflakeMs(t);
  if (ms !== null) {
    return Math.max(0, (Date.now() - ms) / 3600000);
  }
  if (typeof t.age_hours === 'number') return t.age_hours;
  if (typeof t.diff_hours === 'number') return t.diff_hours;
  return 0;
}

function formatDynamicTimeTag(t, mode = 'feed') {
  const age = getTweetAgeHours(t);
  const is24h = age <= 24;
  let text = '';
  if (age < 1) {
    const mins = Math.max(1, Math.round(age * 60));
    text = `⚡ ${mins}分钟前 (${mode === 'vip' ? '刚刚爆发' : '极速首发'})`;
  } else if (age <= 24) {
    text = `🔥 ${age.toFixed(1)}小时前 (${mode === 'vip' ? '今日爆款' : '24h黄金期'})`;
  } else if (age <= 48) {
    text = `⏱️ ${age.toFixed(1)}小时前 (${mode === 'vip' ? '昨日热帖' : '48h有效'})`;
  } else {
    text = `⚠️ ${age.toFixed(1)}小时前 (超期淘汰)`;
  }
  return { age, is24h, text };
}

