// Update VIP Blogger Chips dynamically
function updateVipBloggersChips() {
  const container = document.getElementById('vip-blogger-chips');
  if (!container) return;

  const list = DATA_BUNDLE.vip_tweets || [];
  const todayList = list.filter(t => getTweetAgeHours(t) <= 24 && t.views >= 50000 && t.likes >= 300);
  const h48List = list.filter(t => getTweetAgeHours(t) <= 48 && t.views >= 50000 && t.likes >= 300);

  // Group authors dynamically from the real followings virals pool
  const authorsMap = new Map();
  list.forEach(t => {
    const u = t.user;
    if (!authorsMap.has(u)) {
      authorsMap.set(u, {
        handle: u,
        name: t.name || u,
        fc: t.fc || 0,
        todayCount: 0,
        h48Count: 0,
        totalCount: 0
      });
    }
    const item = authorsMap.get(u);
    item.totalCount++;
    const age = getTweetAgeHours(t);
    if (age <= 24 && t.views >= 50000 && t.likes >= 300) item.todayCount++;
    if (age <= 48 && t.views >= 50000 && t.likes >= 300) item.h48Count++;
  });

  // Sort authors: those with today's virals first, then by totalCount
  const sortedAuthors = Array.from(authorsMap.values()).sort((a, b) => {
    if (b.todayCount !== a.todayCount) return b.todayCount - a.todayCount;
    return b.totalCount - a.totalCount;
  });

  let chipsHtml = `
    <button class="vip-chip ${currentVipUser === 'all' ? 'active' : ''}" data-user="all">
      🌟 全部关注池博主爆款 (<span id="vip-total-count">${todayList.length}</span>条今日爆款)
    </button>
  `;

  sortedAuthors.forEach(a => {
    const isActive = currentVipUser.toLowerCase() === a.handle.toLowerCase();
    let badgeText = '';
    if (a.todayCount > 0) {
      badgeText = `(${a.todayCount}条今日)`;
    } else if (a.h48Count > 0) {
      badgeText = `(${a.h48Count}条昨日)`;
    }
    chipsHtml += `
      <button class="vip-chip ${isActive ? 'active' : ''}" data-user="${escapeHtml(a.handle)}">
        👑 ${escapeHtml(a.name)} @${escapeHtml(a.handle)} ${badgeText}
      </button>
    `;
  });

  container.innerHTML = chipsHtml;

  // Bind click handlers to newly generated chips
  container.querySelectorAll('.vip-chip').forEach(btn => {
    btn.onclick = () => {
      container.querySelectorAll('.vip-chip').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentVipUser = btn.dataset.user;
      renderVipTweets();
    };
  });
}

function switchToVip48h() {
  document.querySelectorAll('.vip-time-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.time === 'all_48h');
  });
  currentVipTime = 'all_48h';
  renderVipTweets();
}

// 2. Render VIP Special Focus Virals (Dynamic Real-Time Calculation)
function renderVipTweets() {
  const container = document.getElementById('vip-tweets-feed');
  if (!container) return;

  const list = DATA_BUNDLE.vip_tweets || [];
  
  // Refresh badges in chips
  updateVipBloggersChips();

  let filtered = list.filter(t => {
    const age = getTweetAgeHours(t);
    // User filter
    if (currentVipUser !== 'all' && t.user.toLowerCase() !== currentVipUser.toLowerCase()) return false;
    // Track filter
    if (currentTrack !== 'all' && t.track !== currentTrack) return false;
    // Time filter: today only (<=24h) vs all 48h (<=48h)
    if (currentVipTime === 'today' && age > 24) return false;
    if (currentVipTime === 'all_48h' && age > 48) return false;
    // Strict viral threshold: 300+ likes & 50K+ views
    if (t.views < 50000 || t.likes < 300) return false;
    // Tier filter
    if (currentVipTier === '200k' && t.views < 200000) return false;
    if (currentVipTier === '100k' && t.views < 100000) return false;
    if (currentVipTier === '50k' && t.views < 50000) return false;
    // Search
    if (currentVipSearch) {
      const q = currentVipSearch.toLowerCase();
      const match = t.text.toLowerCase().includes(q) || t.user.toLowerCase().includes(q) || t.name.toLowerCase().includes(q);
      if (!match) return false;
    }
    return true;
  });

  // Sorting: When selecting all (or by default), strictly sort by time: newest first!
  
  // Update dynamic count on 48h button
  const vip48Btn = document.querySelector('.vip-time-btn[data-time="all_48h"]');
  if (vip48Btn) {
    const total48 = list.filter(t => getTweetAgeHours(t) <= 48 && t.views >= 50000 && t.likes >= 300).length;
    vip48Btn.textContent = '⏱️ 近 48 小时窗口 (昨日至今全量 · ' + total48 + '条)';
  }
  const vipTodayBtn = document.querySelector('.vip-time-btn[data-time="today"]');
  if (vipTodayBtn) {
    const totalToday = list.filter(t => getTweetAgeHours(t) <= 24 && t.views >= 50000 && t.likes >= 300).length;
    vipTodayBtn.textContent = '🔥 只看今日爆款 (24h鲜活 · ' + totalToday + '条今日出炉)';
  }

  if (currentVipSort === 'time') {

    filtered.sort((a, b) => getTweetAgeHours(a) - getTweetAgeHours(b)); // newest first
  } else if (currentVipSort === 'views') {
    filtered.sort((a, b) => b.views - a.views);
  } else if (currentVipSort === 'likes') {
    filtered.sort((a, b) => b.likes - a.likes);
  }

  // Update total count indicator in chips
  const totalCounter = document.getElementById('vip-total-count');
  if (totalCounter) {
    const allTodayCount = list.filter(t => getTweetAgeHours(t) <= 24 && t.views >= 50000 && t.likes >= 300).length;
    totalCounter.textContent = allTodayCount;
  }

  if (filtered.length === 0) {
    if (currentVipTime === 'today' && currentVipUser !== 'all') {
      const has48h = list.some(t => t.user.toLowerCase() === currentVipUser.toLowerCase() && getTweetAgeHours(t) <= 48 && t.views >= 50000 && t.likes >= 300);
      if (has48h) {
        container.innerHTML = `
          <div style="color:#64748b; padding:40px; text-align:center; background:#fff; border-radius:12px; border:1px solid #fde68a;">
            <p style="font-size:15px; color:#92400e; font-weight:700; margin-bottom:8px;">该特关博主近 24 小时内暂无新增 300赞+ & 50K+ 爆款</p>
            <p style="font-size:13px; color:#64748b; margin-bottom:14px;">但已成功捕获其 48 小时内的超级爆发记录！</p>
            <button onclick="switchToVip48h()" style="background:#f59e0b; color:#fff; border:none; padding:8px 18px; border-radius:8px; font-weight:700; cursor:pointer;">
              ⏱️ 立即查看近 48 小时爆发记录 ↗
            </button>
          </div>
        `;
        return;
      }
    }
    container.innerHTML = '<div style="color:#64748b; padding:50px; text-align:center; background:#fff; border-radius:12px;">今日暂无达到 300赞+ & 50K+ 的特别关注博主爆款（可切换至「⏱️ 近48小时窗口」查看更多）</div>';
    return;
  }

  container.innerHTML = filtered.map(t => {
    const timeTag = formatDynamicTimeTag(t, 'vip');
    return `
    <div class="vip-tweet-card">
      <div class="tweet-top">
        <div class="tweet-author-box">
          <div class="tweet-avatar" style="background:#f59e0b;">${t.name ? escapeHtml(t.name[0]) : '@'}</div>
          <div>
            <div class="tweet-author-name">
              <span class="t-name">${escapeHtml(t.name)}</span>
              <span class="t-handle">@${escapeHtml(t.user)}</span>
              <span class="vip-focus-badge">⭐ 特别关注博主</span>
              <span class="vip-blogger-tag">👑 粉丝 ${formatNum(t.fc)}</span>
              <span class="tier-badge ${t.tier_class}">${escapeHtml(t.tier_badge)}</span>
              <span class="tweet-time-tag ${timeTag.is24h ? 'urgent-24h' : ''}">${escapeHtml(timeTag.text)}</span>
            </div>
            <div class="tweet-meta-tags">
              <span class="tweet-track-badge">${escapeHtml(t.track_label)}</span>
            </div>
          </div>
        </div>

        <div style="display:flex; gap:8px;">
          <a class="tweet-link-btn primary" href="${t.url}" target="_blank" rel="noopener">🔗 直达推文原帖 ↗</a>
        </div>
      </div>

      <div class="tweet-text">${escapeHtml(t.text)}</div>

      <!-- ONE-ROW METRICS -->
      <div class="vip-metrics-bar">
        <span>👁️ 曝光浏览量 <strong>${formatNum(t.views)}</strong></span>
        <span>❤️ 点赞数 <strong>${formatNum(t.likes)}</strong></span>
        <span>🔁 转推数 <strong>${formatNum(t.retweets)}</strong></span>
        <span style="color:#b45309;">💥 爆发放大率 <strong>${t.ratio ? t.ratio.toFixed(1) : 0}x</strong></span>
      </div>
    </div>
  `}).join('');
}

// 3. Render Low-Fan Pure AI Tweets Feed (Dynamic Real-Time Calculation)
function renderTweetsFeed() {
  const container = document.getElementById('tweets-feed');
  if (!container) return;

  const list = DATA_BUNDLE.tweets || [];
  
  // Update dynamic button badges based on real-time snowflake ages
  const lowfanInTrack = list.filter(t => currentTrack === 'all' || t.track === currentTrack);
  const count24h = lowfanInTrack.filter(t => getTweetAgeHours(t) <= 24).length;
  const count48h = lowfanInTrack.filter(t => getTweetAgeHours(t) <= 48).length;

  const btn24 = document.querySelector('.time-btn[data-time="24h"]');
  if (btn24) {
    btn24.textContent = `🔥 24小时极速爆发 (优先主打 · 当下正热 · ${count24h}条)`;
  }
  const btn48 = document.querySelector('.time-btn[data-time="48h"]');
  if (btn48) {
    btn48.textContent = `⚡ 48小时有效生命期 (最大窗口 · 严格淘汰>48h · ${count48h}条)`;
  }

  let filtered = list.filter(t => {
    const age = getTweetAgeHours(t);
    // Track filter
    if (currentTrack !== 'all' && t.track !== currentTrack) return false;
    // Time filter: strict dynamic cutoffs
    if (currentTime === '24h' && age > 24) return false;
    if (currentTime === '48h' && age > 48) return false;
    // Tier filter
    if (currentTier === '100k' && t.views < 100000) return false;
    if (currentTier === '50k' && t.views < 50000) return false;
    if (currentTier === '10k' && t.views < 10000) return false;
    // Search
    if (currentSearch) {
      const q = currentSearch.toLowerCase();
      const match = t.text.toLowerCase().includes(q) || t.user.toLowerCase().includes(q) || t.name.toLowerCase().includes(q);
      if (!match) return false;
    }
    return true;
  });

  // Sort
  if (currentSort === 'priority_24h') {
    filtered.sort((a, b) => {
      const aAge = getTweetAgeHours(a);
      const bAge = getTweetAgeHours(b);
      const a24 = aAge <= 24 ? 1 : 0;
      const b24 = bAge <= 24 ? 1 : 0;
      if (a24 !== b24) return b24 - a24;
      return b.views - a.views;
    });
  } else if (currentSort === 'time') {
    filtered.sort((a, b) => getTweetAgeHours(a) - getTweetAgeHours(b));
  } else if (currentSort === 'views') {
    filtered.sort((a, b) => b.views - a.views);
  } else if (currentSort === 'ratio') {
    filtered.sort((a, b) => b.ratio - a.ratio);
  }

  const total = filtered.length;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  if (currentPage > totalPages) currentPage = totalPages;

  const startIdx = (currentPage - 1) * PAGE_SIZE;
  const pageItems = filtered.slice(startIdx, startIdx + PAGE_SIZE);

  if (pageItems.length === 0) {
    container.innerHTML = '<div style="color:#64748b; padding:50px; text-align:center; background:#fff; border-radius:12px;">该 AI 赛道暂无符合条件的低粉爆款推文</div>';
    renderPagination(totalPages, total);
    return;
  }

  container.innerHTML = pageItems.map((t, idx) => {
    const timeTag = formatDynamicTimeTag(t, 'feed');
    return `
    <div class="tweet-card">
      <div class="tweet-top">
        <div class="tweet-author-box">
          <div class="tweet-avatar">${t.name ? escapeHtml(t.name[0]) : '@'}</div>
          <div>
            <div class="tweet-author-name">
              <span class="t-name">${escapeHtml(t.name)}</span>
              <span class="t-handle">@${escapeHtml(t.user)}</span>
              <span class="t-badge-lowfan">👤 粉丝 ${formatNum(t.fc)} (AI低粉逆袭)</span>
              ${idx === 0 && currentPage === 1 ? '<span class="hot-badge-top">👑 TOP 1 · 现象级最爆</span>' : ''}
              <span class="tier-badge ${t.tier_class}">${escapeHtml(t.tier_badge)}</span>
              <span class="tweet-time-tag ${timeTag.is24h ? 'urgent-24h' : ''}">${escapeHtml(timeTag.text)}</span>
            </div>
            <div class="tweet-meta-tags">
              <span class="tweet-track-badge">${escapeHtml(t.track_label)}</span>
              <span class="tweet-ratio-badge">🔥 放大 ${t.ratio.toFixed(1)}x</span>
              <span style="color:#64748b; font-size:12px; margin-left:4px;">${escapeHtml(t.viral_reason)}</span>
            </div>
          </div>
        </div>

        <div style="display:flex; gap:8px;">
          <a class="tweet-link-btn primary" href="${t.url}" target="_blank" rel="noopener">🔗 直达推文原帖 ↗</a>
          <button class="tweet-link-btn secondary" onclick="drillBlogger('${t.user}')">👤 穿透博主时间轴</button>
          <a class="tweet-link-btn outline" href="https://x.com/${t.user}" target="_blank" rel="noopener">博主主页 ↗</a>
        </div>
      </div>

      <div class="tweet-text">${escapeHtml(t.text)}</div>

      <!-- ONE-ROW METRICS -->
      <div class="tweet-metrics-bar">
        <span>👁️ 曝光浏览量 <strong>${formatNum(t.views)}</strong></span>
        <span>❤️ 点赞数 <strong>${formatNum(t.likes)}</strong></span>
        <span>🔁 转推数 <strong>${formatNum(t.retweets)}</strong></span>
        <span style="color:#dc2626;">💥 爆发放大率 <strong>${t.ratio.toFixed(1)}x</strong></span>
      </div>
    </div>
  `}).join('');

  renderPagination(totalPages, total);
}

function renderPagination(totalPages, totalItems) {
  const bar = document.getElementById('pagination-bar');
  if (!bar) return;
  if (totalItems <= PAGE_SIZE) {
    bar.innerHTML = `<span style="font-size:13px; color:#64748b;">共 ${totalItems} 条精选 AI 爆款（单页展示完毕）</span>`;
    return;
  }

  let btns = '';
  for (let p = 1; p <= totalPages; p++) {
    btns += `<button class="page-num-btn ${p === currentPage ? 'active' : ''}" data-page="${p}">第 ${p} 页</button>`;
  }

  bar.innerHTML = `
    <span style="font-size:13px; color:#64748b; margin-right:12px;">共 ${totalItems} 条 AI 低粉爆款（每页 ${PAGE_SIZE} 条）</span>
    ${btns}
  `;

  bar.querySelectorAll('.page-num-btn').forEach(btn => {
    btn.onclick = () => {
      currentPage = parseInt(btn.dataset.page);
      renderTweetsFeed();
      const topElem = document.getElementById('tweets-feed-container');
      if (topElem) topElem.scrollIntoView({ behavior: 'smooth' });
    };
  });
}

// 4. Render Blogger Dossier (With 1-Row Metrics & Dynamic Time Tags)
function renderBloggerDossier(handle) {
  const container = document.getElementById('blogger-dossier-content');
  if (!container) return;

  const bloggers = DATA_BUNDLE.key_bloggers || [];
  let blogger = bloggers.find(b => b.handle.toLowerCase() === handle.toLowerCase());
  
  if (!blogger) {
    const vipB = (DATA_BUNDLE.vip_bloggers || []).find(b => b.handle.toLowerCase() === handle.toLowerCase());
    if (vipB) {
      blogger = {
        handle: vipB.handle,
        name: vipB.name,
        fc: vipB.fc,
        desc: vipB.desc,
        track_label: '⭐ 特别关注博主',
        real_signal: `该特别关注博主拥有 ${formatNum(vipB.fc)} 粉丝，近期在推特斩获最高 ${formatNum(vipB.top_views)} 曝光！`,
        tweets: (DATA_BUNDLE.vip_tweets || []).filter(t => t.user.toLowerCase() === handle.toLowerCase())
      };
    }
  }

  if (!blogger) {
    const followObj = ALL_FOLLOWINGS.find(u => u.handle.toLowerCase() === handle.toLowerCase());
    if (followObj) {
      blogger = {
        handle: followObj.handle,
        name: followObj.name,
        fc: followObj.fc,
        desc: '关注池博主',
        track_label: 'AI 探索者',
        real_signal: `粉丝 ${formatNum(followObj.fc)}，已收录于黄总 809 位关注池`,
        tweets: (DATA_BUNDLE.tweets || []).filter(t => t.user.toLowerCase() === handle.toLowerCase())
      };
    }
  }

  if (!blogger) {
    container.innerHTML = '<div style="padding:40px; text-align:center; color:#64748b;">未找到该博主画像档案</div>';
    return;
  }

  container.innerHTML = `
    <div class="dossier-card">
      <div class="dossier-header">
        <div class="dossier-avatar">${blogger.name ? escapeHtml(blogger.name[0]) : '@'}</div>
        <div class="dossier-title-box">
          <div class="dossier-name-row">
            <span class="d-name">${escapeHtml(blogger.name)}</span>
            <span class="d-handle">@${escapeHtml(blogger.handle)}</span>
            <span class="d-fc-badge">👤 粉丝 ${formatNum(blogger.fc)}</span>
            <span class="d-track-badge">${escapeHtml(blogger.track_label)}</span>
          </div>
          <div class="dossier-bio">${escapeHtml(blogger.desc)}</div>
        </div>
        <div>
          <a class="dossier-x-btn" href="https://x.com/${blogger.handle}" target="_blank" rel="noopener">访问推特主页 ↗</a>
        </div>
      </div>

      <div class="dossier-grid">
        <div class="dossier-box">
          <h4>🎯 真实爆款信号与战绩</h4>
          <p>${escapeHtml(blogger.real_signal)}</p>
        </div>
        <div class="dossier-box">
          <h4>🧠 选题与文案复刻策略</h4>
          <p>紧扣该博主的真实选题视角，提炼其高信息密度短句与实机截图风格，将经验拆解转化为我方实操推文。</p>
        </div>
      </div>

      <div class="dossier-tweets-title">
        <h3>📌 代表性爆款推文 (${blogger.tweets ? blogger.tweets.length : 0} 篇)</h3>
      </div>

      <div class="dossier-tweets-list">
        ${blogger.tweets && blogger.tweets.length > 0 ? blogger.tweets.map(t => {
          const timeTag = formatDynamicTimeTag(t, 'feed');
          return `
          <div class="embedded-tweet-card">
            <div class="embedded-tweet-top">
              <div class="embedded-author-info">
                <span class="tier-badge ${t.tier_class}">${escapeHtml(t.tier_badge)}</span>
                <span class="tweet-time-tag ${timeTag.is24h ? 'urgent-24h' : ''}">${escapeHtml(timeTag.text)}</span>
              </div>
              <a class="tweet-link-btn primary" href="${t.url}" target="_blank" rel="noopener">🔗 直达推文原帖 ↗</a>
            </div>
            <div class="embedded-tweet-text">${escapeHtml(t.text)}</div>
            <div class="tweet-metrics-bar">
              <span>👁️ 曝光浏览量 <strong>${formatNum(t.views)}</strong></span>
              <span>❤️ 点赞数 <strong>${formatNum(t.likes)}</strong></span>
              <span>🔁 转推数 <strong>${formatNum(t.retweets)}</strong></span>
              <span style="color:#dc2626;">💥 放大率 <strong>${t.ratio ? t.ratio.toFixed(1) : 0}x</strong></span>
            </div>
          </div>
        `}).join('') : '<div style="color:#64748b; padding:20px; font-size:13.5px;">该博主近期暂无爆款推文记录</div>'}
      </div>
    </div>
  `;
}

function drillBlogger(handle) {
  selectedBloggerHandle = handle;
  switchMode('blogger');
}

// Setup Event Listeners
document.addEventListener('DOMContentLoaded', () => {
  // Mode switcher
  document.getElementById('tab-clusters-btn')?.addEventListener('click', () => switchMode('clusters'));
  document.getElementById('tab-vip-btn')?.addEventListener('click', () => switchMode('vip'));
  document.getElementById('tab-feed-btn')?.addEventListener('click', () => switchMode('feed'));
  document.getElementById('tab-blogger-btn')?.addEventListener('click', () => switchMode('blogger'));

  // Shortcut from Feed to VIP
  document.getElementById('shortcut-to-vip-btn')?.addEventListener('click', () => switchMode('vip'));

  // Track buttons
  document.querySelectorAll('.track-pill').forEach(btn => {
    btn.onclick = () => setTrack(btn.dataset.track);
  });

  // VIP Blogger Chips
  document.querySelectorAll('.vip-chip').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.vip-chip').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentVipUser = btn.dataset.user;
      renderVipTweets();
    };
  });

  // VIP Time Filter
  document.querySelectorAll('.vip-time-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.vip-time-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentVipTime = btn.dataset.time;
      renderVipTweets();
    };
  });

  // VIP Tier Filter
  document.querySelectorAll('.vip-tier-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.vip-tier-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentVipTier = btn.dataset.tier;
      renderVipTweets();
    };
  });

  // VIP Sort
  document.querySelectorAll('.vip-sort-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.vip-sort-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentVipSort = btn.dataset.sort;
      renderVipTweets();
    };
  });

  // VIP Search
  const vipSearchInput = document.getElementById('vip-search-input');
  if (vipSearchInput) {
    vipSearchInput.addEventListener('input', (e) => {
      currentVipSearch = e.target.value.trim();
      renderVipTweets();
    });
  }

  // Low-fan Feed Filters
  document.querySelectorAll('.time-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.time-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentTime = btn.dataset.time;
      currentPage = 1;
      renderTweetsFeed();
    };
  });

  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentTier = btn.dataset.tier;
      currentPage = 1;
      renderTweetsFeed();
    };
  });

  document.querySelectorAll('.sort-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentSort = btn.dataset.sort;
      currentPage = 1;
      renderTweetsFeed();
    };
  });

  const searchInput = document.getElementById('search-input');
  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      currentSearch = e.target.value.trim();
      currentPage = 1;
      renderTweetsFeed();
    });
  }

  // Blogger Chips
  document.querySelectorAll('.blogger-chip').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('.blogger-chip').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      selectedBloggerHandle = btn.dataset.handle;
      renderBloggerDossier(selectedBloggerHandle);
    };
  });

  // Refresh Radar with dynamic clock re-evaluation
  document.getElementById('btn-refresh-radar')?.addEventListener('click', () => {
    const btn = document.getElementById('btn-refresh-radar');
    btn.textContent = '🔄 刷新中...';
    setTimeout(() => {
      btn.textContent = '✅ 已是最新';
      if (currentMode === 'vip') renderVipTweets();
      else if (currentMode === 'feed') renderTweetsFeed();
      else if (currentMode === 'blogger') renderBloggerDossier(selectedBloggerHandle);
      else renderTopicClusters();
      setTimeout(() => { btn.textContent = '刷新实时雷达'; }, 1500);
    }, 400);
  });

  // Dynamic 60s ticker: automatically advances timestamps and reclamps windows
  setInterval(() => {
    if (currentMode === 'vip') renderVipTweets();
    else if (currentMode === 'feed') renderTweetsFeed();
    else if (currentMode === 'blogger') renderBloggerDossier(selectedBloggerHandle);
    else renderTopicClusters();
  }, 60000);

  // Initial render
  renderTopicClusters();
});
